import * as types from "../../../actions/actionTypes";
const initialState = {
  deletedbusstaffdetails: {
    deletedbusstaff: [],
    loading: false,
  },
};
const DeletebusstaffReducer = (
  state = initialState.deletedbusstaffdetails,
  action
) => {
  switch (action.type) {
    case types.DELETE_BUS_STAFF_START:
      // console.log('respin reducer', state);
      return {
        ...state,
        loading: true,
      };
    case types.DELETE_BUS_STAFF_SUCCESS:
      return {
        ...state,
        loading: false,
      };
    case types.DELETE_BUS_STAFF_ERROR:
      return {
        ...state,
        loading: false,
        error: action.payload,
      };
    default:
      return state;
  }
};
export default DeletebusstaffReducer;